// =================== TREE MODELS: Quaternius CC0 trees Phil picked for Earth (2.23.65), converted from .glb (part, color, positions in cm as int16, triangles as uint16) ===================
const TREE_GLB = {"leafy":[["Wood","#6d4b45","",""],["Green","#536d45","",""]],"leafy2":[["Wood","#6d4b45","",""],["Green","#536d45","",""],["DarkGreen","#415536","",""]],"dead2":[["Wood","#6d4b45","",""]]};
TREE_GLB.dead = [TREE_GLB.leafy[0]];   // tree-845 is tree-835's trunk with no leaves
// decode once per kind, then every tree of that kind shares the geometry
const TREE_GEO = {}, TREE_COL = { Wood: ['#6b4f36', 'bark'], Green: ['#5f8a3e', 'leaves'], DarkGreen: ['#46692e', 'leaves'] };
function treeGeo(kind) {
  if (TREE_GEO[kind]) return TREE_GEO[kind];
  const b64 = s => { const bin = atob(s), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u.buffer; };
  return (TREE_GEO[kind] = TREE_GLB[kind].map(([name, , pb, ib]) => {
    const P = new Int16Array(b64(pb)), I = new Uint16Array(b64(ib)), pos = new Float32Array(P.length), uv = new Float32Array(P.length / 3 * 2);
    for (let i = 0; i < P.length; i += 3) { pos[i] = P[i] / 100; pos[i + 1] = P[i + 1] / 100; pos[i + 2] = P[i + 2] / 100; uv[i / 3 * 2] = (pos[i] + pos[i + 2]) * 0.9; uv[i / 3 * 2 + 1] = pos[i + 1] * 0.9; }
    let g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('uv', new THREE.BufferAttribute(uv, 2)); g.setIndex(new THREE.BufferAttribute(I, 1));
    g = g.toNonIndexed(); g.computeVertexNormals();   // faceted, like the original
    return [name, g]; }));
}
// a Quaternius tree: 'leafy', 'leafy2', 'dead' or 'dead2'
function glbTree(kind, s) { const g = new THREE.Group();
  for (const [name, geo] of treeGeo(kind)) { const c = TREE_COL[name] || TREE_COL.Wood; const m = new THREE.Mesh(geo, toon(c[0], c[1])); m.castShadow = m.receiveShadow = true; m.scale.setScalar(s); g.add(m); }
  return g; }
function earthTree(x, z, s, r) { const k = r < 0.45 ? 'leafy' : r < 0.85 ? 'leafy2' : r < 0.93 ? 'dead' : 'dead2';
  at(glbTree(k, 1.75 * s), x, z, x * 7.3, -0.05); solid(x, z, 0.32 * s); }
